'use strict';

function parseNumberList(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseNumberList expects a string');
  }
  const trimmed = text.trim();
  if (trimmed === '') {
    return [];
  }
  return trimmed.split(',').map(function (piece) {
    const token = piece.trim();
    if (token === '') {
      throw new SyntaxError('empty field in "' + text + '"');
    }
    const parsed = Number(token);
    if (Number.isNaN(parsed)) {
      throw new SyntaxError('cannot parse "' + token + '" as a number');
    }
    return parsed;
  });
}

function sumArray(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError('sumArray expects an array');
  }
  let total = 0;
  for (let i = 0; i < arr.length; i += 1) {
    const value = arr[i];
    if (typeof value !== 'number') {
      throw new TypeError('element at index ' + i + ' is not a number');
    }
    if (!Number.isFinite(value)) {
      throw new RangeError('element at index ' + i + ' is not finite');
    }
    total += value;
  }
  return total;
}

function describeSum(arr) {
  const total = sumArray(arr);
  if (arr.length === 0) {
    return 'empty array -> 0';
  }
  const sign = total === 0 ? 'zero' : (total > 0 ? 'positive' : 'negative');
  return arr.join(' + ') + ' = ' + total + ' (' + sign + ')';
}

function report(inputs) {
  const lines = [];
  for (const input of inputs) {
    try {
      const values = typeof input === 'string' ? parseNumberList(input) : input;
      lines.push(describeSum(values));
    } catch (err) {
      const kind = err.name === 'SyntaxError' ? 'bad input' : 'invalid data';
      lines.push(kind + ': ' + err.message);
    }
  }
  return lines.join('\n');
}

function main() {
  const inputs = [
    '1, 2, 3',
    '-1, 0, 1',
    '',
    '2.5, 2.5',
    '4, , 6',
    [10, 20, 30],
    [1, null, 3]
  ];
  console.log(report(inputs));
}

main();

module.exports = { sumArray, parseNumberList, describeSum, report };

