function parseBirthdate(birthdateStr) {
  if (typeof birthdateStr !== 'string') {
    throw new TypeError('birthdate must be a string');
  }
  const parts = birthdateStr.trim().split('-');
  if (parts.length !== 3) {
    throw new Error('birthdate must use the YYYY-MM-DD format');
  }
  const [yearStr, monthStr, dayStr] = parts;
  if (yearStr.length !== 4) {
    throw new Error('year must have four digits');
  }
  if (monthStr.length !== 2) {
    throw new Error('month must have two digits');
  }
  if (dayStr.length !== 2) {
    throw new Error('day must have two digits');
  }
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);
  if (!Number.isInteger(year) || !Number.isInteger(month) || !Number.isInteger(day)) {
    throw new Error('birthdate contains non-numeric components');
  }
  if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
    throw new Error('birthdate is not a real calendar date');
  }
  return { year, month, day };
}

function isLeapYear(year) {
  if (year % 400 === 0) {
    return true;
  }
  if (year % 100 === 0) {
    return false;
  }
  return year % 4 === 0;
}

function daysInMonth(year, month) {
  if (month === 2) {
    return isLeapYear(year) ? 29 : 28;
  }
  const longMonths = [1, 3, 5, 7, 8, 10, 12];
  return longMonths.includes(month) ? 31 : 30;
}

function ageOn(birth, today) {
  const nowMonth = today.getMonth() + 1;
  let age = today.getFullYear() - birth.year;
  if (nowMonth < birth.month) {
    age -= 1;
  } else if (nowMonth === birth.month && today.getDate() < birth.day) {
    age -= 1;
  }
  if (age < 0) {
    throw new Error('birthdate is in the future');
  }
  return age;
}

function calculateAge(birthdateStr) {
  return ageOn(parseBirthdate(birthdateStr), new Date());
}

function describeAge(birthdateStr) {
  const birth = parseBirthdate(birthdateStr);
  const today = new Date();
  const age = ageOn(birth, today);
  const unit = age === 1 ? 'year' : 'years';
  let suffix = '';
  if (today.getMonth() + 1 === birth.month) {
    if (today.getDate() === birth.day) {
      suffix = ' (happy birthday!)';
    }
  }
  return `${birthdateStr}: ${age} ${unit} old${suffix}`;
}

if (require.main === module) {
  for (const arg of process.argv.slice(2)) {
    console.log(describeAge(arg));
  }
}

module.exports = { calculateAge, describeAge, parseBirthdate, isLeapYear, daysInMonth };

