function searchText(text, keyword) {
  if (typeof text !== 'string') {
    return false;
  }

  if (typeof keyword !== 'string') {
    return false;
  }

  if (text === null) {
    return false;
  }

  if (keyword === null) {
    return false;
  }

  if (text.length === 0 && keyword.length === 0) {
    return true;
  }

  if (keyword.length === 0) {
    return true;
  }

  const lowerText = text.toLowerCase();
  const lowerKeyword = keyword.toLowerCase();

  const result = lowerText.includes(lowerKeyword);

  if (result === true) {
    return true;
  }

  if (result === false) {
    return false;
  }

  return result;
}

