  }

  const isDivisibleBy4 = (year % 4 === 0);
  const isDivisibleBy100 = (year % 100 === 0);
  const isDivisibleBy400 = (year % 400 === 0);

  if (isDivisibleBy400 === true) {
    return true;
  }

  if (isDivisibleBy100 === true) {
    return false;
  }

  if (isDivisibleBy4 === true) {
    return true;
  }

  return false;
}

