const WHITESPACE = new Set([' ', '\t', '\n', '\r', '\v', '\f']);

function isWhitespace(ch) {
  if (typeof ch !== 'string') {
    throw new TypeError('isWhitespace expects a single-character string');
  }
  if (ch.length !== 1) {
    throw new RangeError('isWhitespace expects exactly one character');
  }
  return WHITESPACE.has(ch);
}

function removeWhitespace(str) {
  if (typeof str !== 'string') {
    throw new TypeError('removeWhitespace expects a string');
  }
  let out = '';
  for (const ch of str) {
    if (!isWhitespace(ch)) {
      out += ch;
    }
  }
  return out;
}

function countWhitespace(str) {
  return str.length - removeWhitespace(str).length;
}

function collapseWhitespace(str) {
  const parts = [];
  let current = '';
  for (const ch of str) {
    if (isWhitespace(ch)) {
      if (current !== '') {
        parts.push(current);
        current = '';
      }
    } else {
      current += ch;
    }
  }
  if (current !== '') {
    parts.push(current);
  }
  return parts.join(' ');
}

function describe(str) {
  const stripped = removeWhitespace(str);
  const removed = countWhitespace(str);
  const status = removed === 0 ? 'unchanged' : `removed ${removed} whitespace char(s)`;
  const collapsed = collapseWhitespace(str);
  const note = collapsed === stripped ? 'no internal gaps' : `collapsed form: "${collapsed}"`;
  const result = stripped === '' ? 'blank input' : `"${stripped}"`;
  return `"${str}" -> ${result} (${status}; ${note})`;
}

