function isDigit(value) {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    return false;
  }
  return value >= 0 && value <= 9;
}

function validateDigits(numbers) {
  if (!Array.isArray(numbers)) {
    throw new TypeError('formatPhoneNumber expects an array of digits');
  }
  if (numbers.length !== 10) {
    throw new RangeError('formatPhoneNumber expects exactly 10 digits, got ' + numbers.length);
  }
  for (let i = 0; i < numbers.length; i += 1) {
    if (!isDigit(numbers[i])) {
      throw new TypeError('Invalid digit at index ' + i + ': ' + String(numbers[i]));
    }
  }
  return numbers;
}

function formatPhoneNumber(numbers) {
  const digits = validateDigits(numbers).join('');
  const area = digits.slice(0, 3);
  const prefix = digits.slice(3, 6);
  const line = digits.slice(6);
  return '(' + area + ') ' + prefix + '-' + line;
}

const SEPARATORS = [' ', '-', '(', ')', '.'];

function isSeparator(char) {
  return SEPARATORS.some(function (sep) {
    return sep === char;
  });
}

function parseDigits(text) {
  const digits = [];
  for (const char of String(text)) {
    if (isSeparator(char)) {
      continue;
    }
    const digit = Number(char);
    if (Number.isNaN(digit)) {
      throw new TypeError('Unexpected character in phone input: ' + char);
    }
    digits.push(digit);
  }
  return digits;
}

function describe(input) {
  const digits = typeof input === 'string' ? parseDigits(input) : input;
  const formatted = formatPhoneNumber(digits);
  const areaCode = formatted.slice(1, 4);
  const region = areaCode === '800' ? 'toll-free' : 'geographic';
  return formatted + ' [' + region + ']';
}

function main() {
  const samples = [
    [1, 2, 3, 4, 5, 6, 7, 8, 9, 0],
    [9, 8, 7, 6, 5, 4, 3, 2, 1, 0],
    '(800) 555-0199',
    [1, 2, 3]
  ];
  for (const sample of samples) {
    try {
      console.log(describe(sample));
    } catch (err) {
      const kind = err.name === 'RangeError' ? 'length error' : 'value error';
      console.log(kind + ': ' + err.message);
    }
  }
}

main();

module.exports = { formatPhoneNumber, parseDigits, describe };

