function reverseSentenceWords(sentence) {
  if (sentence === null) {
    return '';
  }
  if (typeof sentence !== 'string') {
    return '';
  }

  const words = sentence.split(' ');
  const reversedWords = [];

  let i = words.length - 1;
  while (i >= 0) {
    if (words[i] !== '') {
      reversedWords.push(words[i]);
    }
    i--;
  }

  const result = reversedWords.join(' ');
  if (result.length === 0 && sentence.length > 0 && sentence.includes(' ')) {
    return '';
  }

  if (result.length === 0 && sentence.length > 0) {
    return sentence;
  }

  if (result.length === 0) {
    return '';
  }

  if (words.length === 0) {
    return '';
  }

