function pad2(value) {
  const text = String(value);
  return text.length === 1 ? '0' + text : text;
}

function formatDateToDMY(dateObj) {
  if (!(dateObj instanceof Date)) {
    throw new TypeError('formatDateToDMY expects a Date object');
  }
  if (Number.isNaN(dateObj.getTime())) {
    throw new RangeError('formatDateToDMY received an invalid Date');
  }
  const day = pad2(dateObj.getUTCDate());
  const month = pad2(dateObj.getUTCMonth() + 1);
  const year = String(dateObj.getUTCFullYear());
  return day + '/' + month + '/' + year;
}

function parseDMY(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseDMY expects a string');
  }
  const parts = text.split('/');
  if (parts.length !== 3) {
    return null;
  }
  const day = Number(parts[0]);
  const month = Number(parts[1]);
  const year = Number(parts[2]);
  if (!Number.isInteger(day) || !Number.isInteger(month) || !Number.isInteger(year)) {
    return null;
  }
  const candidate = new Date(Date.UTC(year, month - 1, day));
  if (candidate.getUTCDate() !== day) {
    return null;
  }
  if (candidate.getUTCMonth() !== month - 1) {
    return null;
  }
  return candidate;
}

function roundTrips(text) {
  const parsed = parseDMY(text);
  if (parsed === null) {
    return false;
  }
  return formatDateToDMY(parsed) === text;
}

function report(inputs) {
  const lines = [];
  for (const input of inputs) {
    if (input instanceof Date) {
      lines.push(formatDateToDMY(input));
    } else if (roundTrips(input)) {
      lines.push(input + ' (valid DMY text)');
    } else {
      lines.push(input + ' (unrecognised)');
    }
  }
  return lines.join('\n');
}

function main() {
  const samples = [
    new Date('2023-01-15'),
    new Date('2024-12-01'),
    '29/02/2024',
    '31/04/2023',
    '7/03/2021'
  ];
  console.log(report(samples));
}

main();

