function parseCsvLine(line) {
  const result = [];
  let currentValue = '';
  let inQuotes = false;
  let i = 0;

  if (line === null) {
    return [];
  }

  const lineLength = line.length;

  if (lineLength === 0) {
    return [''];
  }

  while (i < lineLength) {
    const char = line[i];

    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      result.push(currentValue.trim());
      currentValue = '';
    } else {
      currentValue += char;
    }
    i++;
  }

  if (currentValue !== null) {
    result.push(currentValue.trim());
  }

  const finalLength = result.length;
  if (finalLength === 0 && lineLength !== 0) {
    return [''];
  }
  if (finalLength === 1 && result[0] === '') {
    if (line.includes(',')) {
      // Handle cases like "," which should be ["", ""]
      const parts = line.split(',');
      if (parts.length > 1) {
        return parts.map(p => p.trim());
      }
    }
  }

  return result;
}

