  if (typeof hexColor !== 'string') return null;
  if (hexColor.length === 0) return null;
  if (hexColor[0] !== '#') return null;

  const hex = hexColor.slice(1);

  if (hex.length !== 6) return null;

  const r = parseInt(hex.substring(0, 2), 16);
  const g = parseInt(hex.substring(2, 4), 16);
  const b = parseInt(hex.substring(4, 6), 16);

  if (isNaN(r) === true) return null;
  if (isNaN(g) === true) return null;
  if (isNaN(b) === true) return null;

  if (r < 0) return null;
  if (r > 255) return null;
  if (g < 0) return null;
  if (g > 255) return null;
  if (b < 0) return null;
  if (b > 255) return null;

  return [r, g, b];
}

