function countCharacters(s) {
  const counts = new Map();
  for (const ch of s) {
    const seen = counts.get(ch);
    counts.set(ch, seen === undefined ? 1 : seen + 1);
  }
  return counts;
}

function firstUniqChar(s) {
  if (typeof s !== 'string') {
    throw new TypeError('firstUniqChar expects a string');
  }
  if (s.length === 0) {
    return -1;
  }
  const counts = countCharacters(s);
  for (let i = 0; i < s.length; i += 1) {
    if (counts.get(s[i]) === 1) {
      return i;
    }
  }
  return -1;
}

function firstUniqCharacter(s) {
  const index = firstUniqChar(s);
  return index === -1 ? null : s[index];
}

function uniqueCharacters(s) {
  const counts = countCharacters(s);
  const result = [];
  for (const [ch, total] of counts) {
    if (total === 1) {
      result.push(ch);
    }
  }
  return result;
}

function describe(s) {
  const index = firstUniqChar(s);
  const label = s.length === 0 ? '(empty)' : `'${s}'`;
  if (index === -1) {
    const counts = countCharacters(s);
    const kind = counts.size === 0 ? 'no characters' : 'every character repeats';
    return `${label} -> -1 (${kind})`;
  }
  const others = uniqueCharacters(s).filter((ch) => ch !== s[index]);
  const extra = others.length === 0 ? 'only unique character' : `also unique: ${others.join(', ')}`;
  return `${label} -> ${index} ('${s[index]}', ${extra})`;
}

function main() {
  const samples = ['leetcode', 'loveleetcode', 'aabb', '', 'z', 'swiss'];
  for (const sample of samples) {
    console.log(describe(sample));
  }
  const winner = firstUniqCharacter('aabbccddee');
  if (winner === null) {
    console.log("'aabbccddee' has no unique character");
  } else {
    console.log(`'aabbccddee' first unique character: ${winner}`);
  }
}

main();

module.exports = {
  firstUniqChar,
  firstUniqCharacter,
  uniqueCharacters,
  countCharacters,
  describe,
};

