function validateInput(arr, name) {
  if (!Array.isArray(arr)) {
    throw new TypeError(name + ' must be an array');
  }
  for (let i = 0; i < arr.length; i += 1) {
    if (typeof arr[i] !== 'number') {
      throw new TypeError(name + '[' + i + '] must be a number');
    }
    if (Number.isNaN(arr[i])) {
      throw new RangeError(name + '[' + i + '] must not be NaN');
    }
  }
  return arr;
}

function uniqueValues(nums) {
  const seen = [];
  for (const n of nums) {
    let known = false;
    for (const s of seen) {
      if (s === n) {
        known = true;
        break;
      }
    }
    if (!known) {
      seen.push(n);
    }
  }
  return seen;
}

function arrayIntersection(nums1, nums2) {
  validateInput(nums1, 'nums1');
  validateInput(nums2, 'nums2');
  if (nums1.length === 0) {
    return [];
  }
  if (nums2.length === 0) {
    return [];
  }
  const pool = new Set(nums2);
  const result = [];
  for (const n of uniqueValues(nums1)) {
    if (pool.has(n)) {
      result.push(n);
    }
  }
  return result;
}

function formatResult(nums1, nums2) {
  const result = arrayIntersection(nums1, nums2);
  const body = result.length === 0 ? 'empty' : '[' + result.join(', ') + ']';
  return '[' + nums1.join(', ') + '] ∩ [' + nums2.join(', ') + '] = ' + body;
}

function parseRow(line) {
  const halves = line.split('|');
  if (halves.length !== 2) {
    throw new SyntaxError('row must contain exactly one "|" separator');
  }
  return halves.map(function (half) {
    const text = half.trim();
    if (text === '') {
      return [];
    }
    return text.split(/[\s,]+/).map(Number);
  });
}

function main() {
  const rows = [
    '1, 2, 2, 1 | 2, 2',
    '4 9 5 | 9 4 9 8 4',
    '1 3 5 | 2 4 6',
    '7 7 7 |'
  ];
  for (const row of rows) {
    const [a, b] = parseRow(row);
    console.log(formatResult(a, b));
  }
}

main();

module.exports = { arrayIntersection, uniqueValues, validateInput, formatResult, parseRow };

