class Queue {
  constructor(items) {
    this.items = [];
    if (items != undefined) {
      if (!Array.isArray(items)) {
        throw new TypeError('Queue expects an array of initial items');
      }
      for (const item of items) {
        this.enqueue(item);
      }
    }
  }

  enqueue(value) {
    if (value == undefined) {
      throw new TypeError('Cannot enqueue undefined');
    }
    this.items.push(value);
    return this.size();
  }

  dequeue() {
    if (this.isEmpty()) {
      return null;
    }
    return this.items.shift();
  }

  peek() {
    if (this.isEmpty()) {
      return null;
    }
    return this.items[0];
  }

  size() {
    return this.items.length;
  }

  isEmpty() {
    return this.items.length == 0;
  }

  contains(value) {
    return this.items.some((item) => item == value);
  }

  toString() {
    return `Queue(front -> ${this.items.join(', ')})`;
  }
}

function drain(queue) {
  const collected = [];
  let value = queue.dequeue();
  while (value != null) {
    collected.push(value);
    value = queue.dequeue();
  }
  return collected;
}

function removeFirst(queue, target) {
  const kept = [];
  let removed = false;
  for (const value of drain(queue)) {
    if (!removed && value == target) {
      removed = true;
    } else {
      kept.push(value);
    }
  }
  for (const value of kept) {
    queue.enqueue(value);
  }
  return removed;
}

function main() {
  const q = new Queue();
  q.enqueue(1);
  q.enqueue(2);
  console.log('first out:', q.dequeue());

  const tickets = new Queue(['alice', 'bob', 'carol', 'bob']);
  console.log(tickets.toString());
  console.log('front:', tickets.peek());
  console.log('bob waiting:', tickets.contains('bob'));
  console.log('cancelled a bob:', removeFirst(tickets, 'bob'));
  console.log('cancelled a dave:', removeFirst(tickets, 'dave'));
  console.log('served order:', drain(tickets).join(' -> '));
  console.log('empty dequeue returns null:', tickets.dequeue() == null);

  try {
    tickets.enqueue(undefined);
  } catch (err) {
    console.log('rejected:', err.message);
  }
}

main();

