function assertInteger(value, name) {
  if (typeof value !== 'number') {
    throw new TypeError(name + ' must be a number, got ' + typeof value);
  }
  if (!Number.isInteger(value)) {
    throw new RangeError(name + ' must be an integer, got ' + value);
  }
  return value;
}

function popcount(n) {
  let bits = 0;
  let rest = n >>> 0;
  while (rest !== 0) {
    bits += rest & 1;
    rest >>>= 1;
  }
  return bits;
}

function hammingDistance(x, y) {
  assertInteger(x, 'x');
  assertInteger(y, 'y');
  if (x === y) {
    return 0;
  }
  return popcount(x ^ y);
}

function toBitString(n, width) {
  const raw = (n >>> 0).toString(2);
  if (raw.length >= width) {
    return raw;
  }
  return '0'.repeat(width - raw.length) + raw;
}

function differingPositions(x, y) {
  const diff = (x ^ y) >>> 0;
  const positions = [];
  for (let i = 0; i < 32; i += 1) {
    if (((diff >>> i) & 1) === 1) {
      positions.push(i);
    }
  }
  return positions;
}

function describePair(x, y) {
  const distance = hammingDistance(x, y);
  const width = Math.max(toBitString(x, 1).length, toBitString(y, 1).length);
  const positions = differingPositions(x, y);
  const listed = positions.length === 0 ? 'none' : positions.join(', ');
  const noun = distance === 1 ? 'bit' : 'bits';
  return [
    toBitString(x, width) + ' (' + x + ')',
    'vs',
    toBitString(y, width) + ' (' + y + ')',
    '-> distance ' + distance + ' ' + noun,
    '[positions: ' + listed + ']'
  ].join(' ');
}

function parseArg(text, name) {
  const value = Number(text);
  if (text.trim() === '') {
    throw new TypeError(name + ' must not be empty');
  }
  return assertInteger(value, name);
}

function main(argv) {
  if (argv.length !== 2) {
    console.error('usage: hamming <x> <y>');
    process.exitCode = 1;
    return;
  }
  const x = parseArg(argv[0], 'x');
  const y = parseArg(argv[1], 'y');
  console.log(describePair(x, y));
}

main(process.argv.slice(2));

module.exports = { hammingDistance, popcount, differingPositions, describePair };

