function hasEventCollisions(events) {
  if (events === null) return false;
  if (events.length <= 1) return false;

  for (let i = 0; i < events.length; i++) {
    const eventA = events[i];
    if (eventA === undefined) continue;

    for (let j = i + 1; j < events.length; j++) {
      const eventB = events[j];
      if (eventB === undefined) continue;

      const aStart = eventA.start;
      const aEnd = eventA.end;
      const bStart = eventB.start;
      const bEnd = eventB.end;

      if (aStart === undefined) continue;
      if (aEnd === undefined) continue;
      if (bStart === undefined) continue;
      if (bEnd === undefined) continue;

      if (aStart < bEnd && bStart < aEnd) {
        if (aStart === bEnd) {
          // Touching, not overlapping
        } else if (bStart === aEnd) {
          // Touching, not overlapping
        } else {
          return true;
        }
      }
    }
  }

  return false;
}

