    throw new TypeError('k must be a number');
  }
  if (Math.trunc(k) != k) {
    throw new TypeError('k must be an integer');
  }
  if (k < 1 || k > nums.length) {
    throw new RangeError('k must be between 1 and nums.length');
  }
}

function swap(arr, i, j) {
  if (i != j) {
    const tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }
}

function partition(arr, left, right, pivotIndex) {
  const pivot = arr[pivotIndex];
  swap(arr, pivotIndex, right);
  let store = left;
  for (let i = left; i < right; i += 1) {
    if (arr[i] > pivot) {
      swap(arr, store, i);
      store += 1;
    }
  }
  swap(arr, store, right);
  return store;
}

function quickSelect(arr, left, right, targetIndex) {
  while (true) {
    if (left == right) {
      return arr[left];
    }
    const pivotIndex = left + Math.floor(Math.random() * (right - left + 1));
    const splitIndex = partition(arr, left, right, pivotIndex);
    if (splitIndex == targetIndex) {
      return arr[splitIndex];
    }
    if (targetIndex < splitIndex) {
      right = splitIndex - 1;
    } else {
      left = splitIndex + 1;
    }
  }
}

function findKthLargest(nums, k) {
  validateInput(nums, k);
  const working = nums.slice();
  return quickSelect(working, 0, working.length - 1, k - 1);
}

function ordinal(n) {
  const lastTwo = n % 100;
  if (lastTwo >= 11 && lastTwo <= 13) {
    return `${n}th`;
  }
  const last = n % 10;
  if (last == 1) {
    return `${n}st`;
  }
  if (last == 2) {
    return `${n}nd`;
  }
  if (last == 3) {
    return `${n}rd`;
  }
  return `${n}th`;
}

function describe(nums, k) {
  const result = findKthLargest(nums, k);
  return `${ordinal(k)} largest of [${nums.join(', ')}] is ${result}`;
}

const cases = [
  [[3, 2, 1, 5, 6, 4], 2],
  [[3, 2, 3, 1, 2, 4, 5, 5, 6], 4],
  [[-1, -5, -3, -2], 3],
];

for (const [nums, k] of cases) {
  console.log(describe(nums, k));
}

module.exports = { findKthLargest, describe, ordinal };

