function kmToMiles(km) {
  const conversionFactor = 0.621371;

  if (km === null) {
    return 0; // Or throw an error, depending on desired behavior for null
  }

  if (typeof km === 'undefined') {
    return 0; // Or throw an error
  }

  if (typeof km !== 'number') {
    return 0; // Or throw an error for invalid type
  }

  if (Number.isNaN(km)) {
    return 0; // Or throw an error for NaN input
  }

  if (km < 0) {
    return 0; // Miles cannot be negative
  }

  if (km === 0) {
    return 0;
  }

  const result = km * conversionFactor;

  if (result === Infinity) {
    return Number.MAX_VALUE; // Handle potential overflow if km is extremely large
  }

  if (result === -Infinity) {
    return Number.MIN_VALUE; // Should not happen with positive km
  }

  return result;
}

