function isInnerMark(ch) {
  if (ch === "'") {
    return true;
  }
  return ch === '\u2019';
}

function trimMarks(word) {
  let start = 0;
  let end = word.length;
  while (start < end && isInnerMark(word[start])) {
    start += 1;
  }
  while (end > start && isInnerMark(word[end - 1])) {
    end -= 1;
  }
  return word.slice(start, end);
}

function tokenize(text) {
  if (typeof text !== 'string') {
    throw new TypeError('wordFrequency expects a string');
  }
  const words = [];
  let current = '';
  for (const ch of text) {
    const lower = ch.toLowerCase();
    const isLetter = lower >= 'a' && lower <= 'z';
    const isDigit = ch >= '0' && ch <= '9';
    if (isLetter || isDigit) {
      current += lower;
    } else if (isInnerMark(ch) && current !== '') {
      current += "'";
    } else if (current !== '') {
      words.push(trimMarks(current));
      current = '';
    }
  }
  if (current !== '') {
    words.push(trimMarks(current));
  }
  return words;
}

function wordFrequency(text) {
  const counts = {};
  for (const word of tokenize(text)) {
    if (counts[word] === undefined) {
      counts[word] = 1;
    } else {
      counts[word] += 1;
    }
  }
  return counts;
}

function formatReport(counts) {
  const entries = Object.keys(counts).map((word) => [word, counts[word]]);
  entries.sort((a, b) => {
    if (a[1] !== b[1]) {
      return b[1] - a[1];
    }
    return a[0] < b[0] ? -1 : 1;
  });
  return entries
    .map(([word, count]) => {
      const label = count === 1 ? 'time' : 'times';
      return `${word}: ${count} ${label}`;
    })
    .join('\n');
}

function main() {
  const samples = [
    'Hello world, hello!',
    'One two one.',
    "It's a well-known fact -- it's a fact!",
    '   '
  ];
  for (const sample of samples) {
    const counts = wordFrequency(sample);
    console.log(`Input: ${sample}`);
    console.log(JSON.stringify(counts));
    const distinct = Object.keys(counts).length;
    console.log(distinct === 0 ? '(no words found)' : formatReport(counts));
    console.log('');
  }
}

main();

module.exports = { wordFrequency, tokenize, formatReport };

