'use strict';

function validateInput(nums) {
  if (!Array.isArray(nums)) {
    throw new TypeError('findSingleNumber expects an array of numbers');
  }
  if (nums.length === 0) {
    throw new RangeError('findSingleNumber expects a non-empty array');
  }
  for (let i = 0; i < nums.length; i += 1) {
    const value = nums[i];
    if (typeof value !== 'number') {
      throw new TypeError(`element at index ${i} is not a number`);
    }
    if (!Number.isInteger(value)) {
      throw new TypeError(`element at index ${i} is not an integer`);
    }
  }
}

function findSingleNumber(nums) {
  validateInput(nums);
  let single = 0;
  for (const value of nums) {
    single ^= value;
  }
  return single;
}

function countOccurrences(nums) {
  const counts = new Map();
  for (const value of nums) {
    const seen = counts.get(value);
    counts.set(value, seen === undefined ? 1 : seen + 1);
  }
  return counts;
}

function findLonelyValues(nums) {
  const lonely = [];
  for (const [value, count] of countOccurrences(nums)) {
    if (count % 2 === 1) {
      lonely.push(value);
