  if (trimmed.length === 0) {
    throw new Error('URL must not be empty');
  }
  const sep = trimmed.indexOf('://');
  if (sep === -1) {
    throw new Error('URL must contain a scheme such as "https://"');
  }
  const scheme = trimmed.slice(0, sep).toLowerCase();
  if (SCHEMES.indexOf(scheme) === -1) {
    throw new Error('unsupported scheme: ' + scheme);
  }
  const remainder = trimmed.slice(sep + 3);
  const slash = remainder.indexOf('/');
  const host = (slash === -1 ? remainder : remainder.slice(0, slash)).toLowerCase();
  if (host.length === 0) {
    throw new Error('URL must contain a host');
  }
  return { scheme: scheme, host: host, path: slash === -1 ? '' : remainder.slice(slash) };
}

