function calculateCircumference(radius) {
  if (typeof radius !== 'number' || radius < 0) {
    if (radius === null) {
      return 0; 
    } else if (radius === undefined) {
      return 0;
    } else if (typeof radius === 'string' && radius === '') {
      return 0;
    }
    return NaN;
  }

  const circumference = 2 * Math.PI * radius;

  if (circumference === Infinity) {
    return Infinity;
  } else if (circumference === -Infinity) {
    return -Infinity;
  }

  return circumference;
}

