function invertObject(obj) {
  if (obj === null) {
    throw new TypeError('invertObject expects a non-null object');
  }
  if (typeof obj !== 'object') {
    throw new TypeError('invertObject expects an object');
  }
  const inverted = {};
  for (const key of Object.keys(obj)) {
    const value = obj[key];
    if (typeof value === 'symbol') {
      throw new TypeError(`value at "${key}" cannot be stringified`);
    }
    inverted[String(value)] = key;
  }
  return inverted;
}

function findDuplicateValue(obj) {
  const seen = new Map();
  for (const key of Object.keys(obj)) {
    const stringified = String(obj[key]);
    if (seen.has(stringified)) {
      return { value: stringified, keys: [seen.get(stringified), key] };
    }
    seen.set(stringified, key);
  }
  return null;
}

function isInvertible(obj) {
  return findDuplicateValue(obj) === null;
}

function isRoundTrippable(obj) {
  const back = invertObject(invertObject(obj));
  const keys = Object.keys(obj);
  if (keys.length !== Object.keys(back).length) {
    return false;
  }
  return keys.every((key) => back[key] === String(obj[key]));
}

function formatObject(obj) {
  const parts = Object.keys(obj).map((key) => {
    const value = obj[key];
    const shown = typeof value === 'string' ? `'${value}'` : String(value);
    return `'${key}': ${shown}`;
  });
  return parts.length === 0 ? '{}' : `{ ${parts.join(', ')} }`;
}

function report(obj) {
  const duplicate = findDuplicateValue(obj);
  if (duplicate !== null) {
    const [first, second] = duplicate.keys;
    return `${formatObject(obj)} -> unsafe: "${first}" and "${second}" share ${duplicate.value}`;
  }
  const inverted = invertObject(obj);
  const suffix = isRoundTrippable(obj) ? '' : ' (values were coerced to strings)';
  return `${formatObject(obj)} -> ${formatObject(inverted)}${suffix}`;
}

function main() {
  const samples = [
    { a: 1, b: 2 },
    { name: 'Alice', age: 30 },
    { x: 'dup', y: 'dup' },
    {},
  ];
  for (const sample of samples) {
    console.log(report(sample));
  }
  const flags = { enabled: true, verbose: false };
  const invertedFlags = invertObject(flags);
  console.log(`lookup of 'true' gives ${invertedFlags['true']}`);
  console.log(`flags invertible: ${isInvertible(flags)}`);
}

main();

module.exports = { invertObject, isInvertible, findDuplicateValue, isRoundTrippable, formatObject, report };

