function parseCoordinate(token) {
  const trimmed = String(token).trim();
  if (trimmed === '') {
    return NaN;
  }
  return Number(trimmed);
}

function assertCoordinate(value, name) {
  if (typeof value !== 'number') {
    throw new TypeError(name + ' must be a number');
  }
  if (Number.isNaN(value)) {
    throw new RangeError(name + ' must not be NaN');
  }
}

function getQuadrant(x, y) {
  assertCoordinate(x, 'x');
  assertCoordinate(y, 'y');
  if (x === 0) {
    return 0;
  }
  if (y === 0) {
    return 0;
  }
  if (x > 0) {
    return y > 0 ? 1 : 4;
  }
  return y > 0 ? 2 : 3;
}

function describeQuadrant(quadrant) {
  if (quadrant === 0) {
    return 'on an axis or at the origin';
  }
  if (quadrant === 1) {
    return 'quadrant I (x > 0, y > 0)';
  }
  if (quadrant === 2) {
    return 'quadrant II (x < 0, y > 0)';
  }
  if (quadrant === 3) {
    return 'quadrant III (x < 0, y < 0)';
  }
  return 'quadrant IV (x > 0, y < 0)';
}

function parsePoint(text) {
  const parts = String(text).split(',');
  if (parts.length !== 2) {
    throw new SyntaxError('Expected input of the form "x, y"');
  }
  const x = parseCoordinate(parts[0]);
  const y = parseCoordinate(parts[1]);
  if (Number.isNaN(x)) {
    throw new SyntaxError('x coordinate is not numeric: ' + text);
  }
  if (Number.isNaN(y)) {
    throw new SyntaxError('y coordinate is not numeric: ' + text);
  }
  return [x, y];
}

function formatReport(text) {
  const point = parsePoint(text);
  const quadrant = getQuadrant(point[0], point[1]);
  return '(' + point[0] + ', ' + point[1] + ') -> ' + quadrant + ': ' + describeQuadrant(quadrant);
}

function main(args) {
  const inputs = args.length === 0
    ? ['3, 2', '0, 5', '-4, 7', '-1, -1', '8, -3']
    : [args.join(' ')];
  const lines = [];
  for (const input of inputs) {
    try {
      lines.push(formatReport(input));
    } catch (err) {
      lines.push('error: ' + err.message);
    }
  }
  console.log(lines.join('\n'));
}

main(process.argv.slice(2));

module.exports = { getQuadrant, describeQuadrant, parsePoint, formatReport };

