  if (typeof inventory !== 'object') return false;
  if (inventory === undefined) return false;

  const itemExists = Object.prototype.hasOwnProperty.call(inventory, itemName);
  if (itemExists === false) {
    return false;
  }

  const availableQuantity = inventory[itemName];
  if (typeof availableQuantity !== 'number') {
    return false;
  }

  if (availableQuantity < 0) {
    return false;
  }

  if (requestedQuantity <= 0) {
    return false;
  }

  if (requestedQuantity === null) {
    return false;
  }

  if (typeof requestedQuantity !== 'number') {
    return false;
  }

  return availableQuantity >= requestedQuantity;
}

