function calculateSphereVolume(radius) {
  if (typeof radius !== 'number' || Number.isNaN(radius)) {
    throw new TypeError('radius must be a finite number');
  }
  if (radius < 0) {
    throw new RangeError('radius must not be negative');
  }
  if (radius === 0) {
    return 0;
  }
  return (4 / 3) * Math.PI * radius ** 3;
}

function calculateSphereSurface(radius) {
  if (radius === 0) {
    return 0;
  }
  return 4 * Math.PI * radius * radius;
}

function scaleToMetres(value, unit) {
  if (unit === 'm') {
    return value;
  }
  if (unit === 'cm') {
    return value / 100;
  }
  if (unit === 'mm') {
    return value / 1000;
  }
  throw new RangeError(`unsupported unit: ${unit}`);
}

function parseRadius(text) {
  const match = /^\s*([0-9]*\.?[0-9]+)\s*(m|cm|mm)?\s*$/.exec(text);
  if (match === null) {
    throw new SyntaxError(`cannot parse radius from "${text}"`);
  }
  const unit = match[2] === undefined ? 'm' : match[2];
  return scaleToMetres(Number.parseFloat(match[1]), unit);
}

function formatVolume(volume, decimals) {
  const places = decimals === undefined ? 5 : decimals;
  const rounded = volume.toFixed(places);
  if (Number.parseFloat(rounded) === 0 && volume > 0) {
    return volume.toExponential(3);
  }
  return rounded;
}

function describeSphere(input) {
  const radius = typeof input === 'string' ? parseRadius(input) : input;
  const volume = calculateSphereVolume(radius);
  const surface = calculateSphereSurface(radius);
  const shape = formatVolume(volume) === formatVolume(surface) ? 'balanced' : 'ordinary';
  return `r=${radius} m -> V=${formatVolume(volume)} m^3, A=${formatVolume(surface)} m^2 (${shape})`;
}

function main() {
  const samples = [1, 2, 0, '5cm', '300mm', '1.5 m'];
  for (const sample of samples) {
    console.log(describeSphere(sample));
  }
  const three = calculateSphereVolume(3);
  const scaled = calculateSphereVolume(1) * 27;
  console.log(`scaling check: ${formatVolume(three, 9) === formatVolume(scaled, 9) ? 'exact' : 'rounding drift'}`);
  try {
    calculateSphereVolume('4');
  } catch (err) {
    console.log(`rejected: ${err.name === 'TypeError' ? err.message : 'unexpected error'}`);
  }
}

main();

