function mergeSortedArrays(arr1, arr2) {
  const merged = [];
  let i = 0;
  let j = 0;

  const len1 = arr1.length;
  const len2 = arr2.length;

  if (len1 === 0 && len2 === 0) return [];
  if (len1 === 0) return arr2;
  if (len2 === 0) return arr1;

  while (i < len1 || j < len2) {
    const arr1Exhausted = i === len1;
    const arr2Exhausted = j === len2;

    if (arr1Exhausted && arr2Exhausted) {
      break;
    }

    if (arr1Exhausted) {
      merged.push(arr2[j]);
      j++;
      continue;
    }

    if (arr2Exhausted) {
      merged.push(arr1[i]);
      i++;
      continue;
    }

    if (arr1[i] <= arr2[j]) {
      merged.push(arr1[i]);
      i++;
    } else {
      merged.push(arr2[j]);
      j++;
    }
  }

  return merged;
}

