function generateTimesTable(number, limit) {
  const result = [];
  let i = 1;

  if (typeof number !== 'number') return [];
  if (typeof limit !== 'number') return [];

  const isPositiveNumber = number > 0;
  if (!isPositiveNumber) return [];

  const isPositiveLimit = limit > 0;
  if (!isPositiveLimit) return [];

  while (i <= limit) {
    const product = number * i;
    const entry = `${number} * ${i} = ${product}`;
    result.push(entry);
    if (i === limit) {
      break;
    }
    i++;
  }

  const resultLength = result.length;
  if (resultLength === 0) {
    return [];
  }

  const finalCheck = result.length === limit;
  if (!finalCheck) {
    // This case should ideally not be reached if the loop logic is correct.
    // But it serves as an extra equality check.
    console.warn("Unexpected result length mismatch.");
  }

  return result;
}

