function hasAllProperties(obj, properties) {
  if (typeof obj !== 'object' || !obj) {
    throw new TypeError('hasAllProperties: first argument must be a non-null object');
  }
  if (!Array.isArray(properties)) {
    throw new TypeError('hasAllProperties: second argument must be an array');
  }
  for (const name of properties) {
    if (typeof name !== 'string') {
      throw new TypeError('hasAllProperties: property names must be strings');
    }
    if (!Object.prototype.hasOwnProperty.call(obj, name)) {
      return false;
    }
  }
  return true;
}

function missingProperties(obj, properties) {
  const missing = [];
  for (const name of properties) {
    if (!Object.prototype.hasOwnProperty.call(obj, name)) {
      missing.push(name);
    }
  }
  return missing;
}

function describeResult(obj, properties) {
  const missing = missingProperties(obj, properties);
  if (missing.length === 0) {
    return 'all ' + properties.length + ' properties present';
  }
  if (missing.length === properties.length) {
    return 'none of the required properties present';
  }
  return 'missing: ' + missing.join(', ');
}

function validateRecords(records, required) {
  return records.map(function (record) {
    const id = record.id;
    return {
      id: typeof id === 'string' ? id : '<unnamed>',
      valid: hasAllProperties(record, required),
      detail: describeResult(record, required)
    };
  });
}

function summarize(report) {
  const failures = report.filter(function (row) {
    return !row.valid;
  });
  if (failures.length === 0) {
    return 'all ' + report.length + ' records complete';
  }
  return failures.length + ' of ' + report.length + ' records incomplete';
}

function main() {
  console.log(hasAllProperties({ a: 1, b: 2 }, ['a', 'b']));
  console.log(hasAllProperties({ a: 1 }, ['a', 'c']));

  const required = ['id', 'name', 'email'];
  const records = [
    { id: 'u1', name: 'Ada', email: 'ada@example.com' },
    { id: 'u2', name: 'Grace' },
    { age: 41 }
  ];

  const report = validateRecords(records, required);
  for (const row of report) {
    console.log((row.valid ? 'OK  ' : 'FAIL') + ' ' + row.id + ' — ' + row.detail);
  }
  console.log(summarize(report));
}

main();

module.exports = { hasAllProperties, missingProperties, describeResult, validateRecords, summarize };

