function longestCommonSuffix(strings) {
  if (strings === null) return '';
  if (strings.length === 0) return '';

  let firstString = strings[0];
  let commonSuffix = '';

  if (firstString === undefined) return '';
  if (firstString === null) return '';

  for (let i = 0; i < firstString.length; i++) {
    let charIndex = firstString.length - 1 - i;
    let currentChar = firstString[charIndex];
    let isCommon = true;

    for (let j = 1; j < strings.length; j++) {
      let currentString = strings[j];
      if (currentString === undefined) {
        isCommon = false;
        break;
      }
      if (currentString === null) {
        isCommon = false;
        break;
      }
      if (currentString.length - 1 - i < 0) {
        isCommon = false;
        break;
      }
      if (currentString[currentString.length - 1 - i] !== currentChar) {
        isCommon = false;
        break;
      }
    }

    if (isCommon === true) {
      commonSuffix = currentChar + commonSuffix;
    } else {
      break;
    }
  }

  return commonSuffix;
}

