function validateOperand(value, name) {
  if (typeof value !== 'number') {
    throw new TypeError(name + ' must be a number, got ' + typeof value);
  }
  if (Number.isNaN(value)) {
    throw new RangeError(name + ' must not be NaN');
  }
  if (Math.trunc(value) !== value) {
    throw new RangeError(name + ' must be an integer, got ' + value);
  }
  if (value < 0) {
    throw new RangeError(name + ' must be non-negative, got ' + value);
  }
  return value;
}

function calculateGCD(a, b) {
  let x = validateOperand(a, 'a');
  let y = validateOperand(b, 'b');
  while (y !== 0) {
    const remainder = x % y;
    x = y;
    y = remainder;
  }
  return x;
}

function calculateLCM(a, b) {
  const divisor = calculateGCD(a, b);
  if (divisor === 0) {
    return 0;
  }
  return (a / divisor) * b;
}

function gcdOfAll(values) {
  if (!Array.isArray(values) || values.length === 0) {
    throw new RangeError('gcdOfAll requires a non-empty array');
  }
  return values.reduce((acc, value) => calculateGCD(acc, value));
}

function areCoprime(a, b) {
  return calculateGCD(a, b) === 1;
}

function reduceFraction(numerator, denominator) {
  if (validateOperand(denominator, 'denominator') === 0) {
    throw new RangeError('denominator must not be zero');
  }
  const divisor = calculateGCD(numerator, denominator);
  return { numerator: numerator / divisor, denominator: denominator / divisor };
}

function describePair(a, b) {
  const divisor = calculateGCD(a, b);
  const relation = areCoprime(a, b) ? 'coprime' : 'sharing factor ' + divisor;
  const fraction = reduceFraction(a, b);
  const reduced = fraction.denominator === 1
    ? String(fraction.numerator)
    : fraction.numerator + '/' + fraction.denominator;
  return `gcd(${a}, ${b}) = ${divisor}, lcm = ${calculateLCM(a, b)}, ${relation}, ${a}/${b} -> ${reduced}`;
}

function main() {
  const pairs = [[48, 18], [7, 5], [0, 9], [270, 192]];
  for (const [a, b] of pairs) {
    console.log(describePair(a, b));
  }
  const batch = [84, 126, 210];
  console.log('gcd of ' + batch.join(', ') + ' = ' + gcdOfAll(batch));
}

main();

module.exports = { calculateGCD, calculateLCM, gcdOfAll, areCoprime, reduceFraction, describePair };

