// Locate and report the maximum value of a numeric array, driven from the command line.

function isNumeric(value) {
  return typeof value === 'number' && !Number.isNaN(value);
}

function parseNumber(token) {
  const trimmed = token.trim();
  if (trimmed === '') {
    throw new TypeError('empty argument is not a number');
  }
  const value = Number(trimmed);
  if (!isNumeric(value)) {
    throw new TypeError('"' + token + '" is not a number');
  }
  return value;
}

function validate(numbers) {
  if (!Array.isArray(numbers)) {
    throw new TypeError('findMax expects an array');
  }
  if (numbers.length === 0) {
    throw new RangeError('findMax expects a non-empty array');
  }
  for (let i = 0; i < numbers.length; i += 1) {
    if (!isNumeric(numbers[i])) {
      throw new TypeError('element at index ' + i + ' is not a number');
    }
  }
}

function findMax(numbers) {
  validate(numbers);
  let max = numbers[0];
  for (let i = 1; i < numbers.length; i += 1) {
    if (numbers[i] > max) {
      max = numbers[i];
    }
  }
  return max;
}

function indexOfMax(numbers) {
  const max = findMax(numbers);
  let index = 0;
  while (numbers[index] !== max) {
    index += 1;
  }
  return index;
}

function countOccurrences(numbers, target) {
  let count = 0;
  for (const value of numbers) {
    if (value === target) {
      count += 1;
    }
  }
  return count;
}

function describe(numbers) {
  const max = findMax(numbers);
  const at = indexOfMax(numbers);
  const times = countOccurrences(numbers, max);
  const position = times === 1 ? 'index ' + at : 'first at index ' + at + ', ' + times + ' times';
  return '[' + numbers.join(', ') + '] -> max ' + max + ' (' + position + ')';
}

function main(argv) {
  if (argv.length === 0) {
    console.error('usage: findmax <number> [number ...]');
    return 1;
  }
  try {
    console.log(describe(argv.map(parseNumber)));
  } catch (err) {
    console.error(err.message);
    return 1;
  }
  return 0;
}

process.exitCode = main(process.argv.slice(2));

module.exports = { findMax, indexOfMax, countOccurrences, describe, parseNumber };

