'use strict';

function isNaNValue(value) {
  return typeof value === 'number' && Number.isNaN(value);
}

function sameValue(a, b) {
  if (a === b) {
    return true;
  }
  return isNaNValue(a) && isNaNValue(b);
}

function arrayContains(arr, element) {
  if (!Array.isArray(arr)) {
    throw new TypeError('arrayContains: first argument must be an array');
  }
  for (let i = 0; i < arr.length; i += 1) {
    if (sameValue(arr[i], element)) {
      return true;
    }
  }
  return false;
}

function indexOfElement(arr, element) {
  if (!Array.isArray(arr)) {
    throw new TypeError('indexOfElement: first argument must be an array');
  }
  for (let i = 0; i < arr.length; i += 1) {
    if (sameValue(arr[i], element)) {
      return i;
    }
  }
  return -1;
}

function countOccurrences(arr, element) {
  let total = 0;
  for (let i = 0; i < arr.length; i += 1) {
    if (sameValue(arr[i], element)) {
      total += 1;
    }
  }
  return total;
}

function describe(value) {
  if (value === null) {
    return 'null';
  }
  if (typeof value === 'string') {
    return "'" + value + "'";
  }
  if (isNaNValue(value)) {
    return 'NaN';
  }
  return String(value);
}

function report(arr, element) {
  const found = arrayContains(arr, element);
  const parts = arr.map(describe).join(', ');
  const position = indexOfElement(arr, element);
  let detail = 'not present';
  if (position !== -1) {
    detail = 'index ' + position + ', ' + countOccurrences(arr, element) + 'x';
  }
  return '[' + parts + '] contains ' + describe(element) + ' -> ' + found + ' (' + detail + ')';
}

