  [[1, 2, 3], 2],
  [['a', 'b'], 'c'],
  [[0, NaN, 0, NaN], NaN],
  [[1, '1', true], '1'],
  [[null, undefined], undefined],
  [[], 5]
];

for (const [arr, element] of queries) {
  console.log(report(arr, element));
}

