function countInArray(arr, element) {
  if (!Array.isArray(arr)) {
    throw new TypeError('countInArray expects an array as its first argument');
  }
  let count = 0;
  for (let i = 0; i < arr.length; i += 1) {
    if (arr[i] == element) {
      count += 1;
    }
  }
  return count;
}

function uniqueValues(arr) {
  const seen = [];
  for (const value of arr) {
    if (countInArray(seen, value) == 0) {
      seen.push(value);
    }
  }
  return seen;
}

function mostFrequent(arr) {
  if (arr.length == 0) {
    return null;
  }
  let best = null;
  let bestCount = 0;
  for (const value of uniqueValues(arr)) {
    const count = countInArray(arr, value);
    if (count > bestCount) {
      best = value;
      bestCount = count;
    }
  }
  return { value: best, count: bestCount };
}

function formatValue(value) {
  if (typeof value == 'string') {
    return `'${value}'`;
  }
  if (value == null) {
    return 'null';
  }
  return String(value);
}

function describeCount(arr, element) {
  const count = countInArray(arr, element);
  if (count == 0) {
    return `${formatValue(element)} does not appear in the array`;
  }
  const times = count == 1 ? 'time' : 'times';
  return `${formatValue(element)} appears ${count} ${times}`;
}

function report(arr, elements) {
  const lines = elements.map((element) => describeCount(arr, element));
  const top = mostFrequent(arr);
  if (top == null) {
    lines.push('the array is empty, so there is no most frequent value');
  } else {
    lines.push(`most frequent: ${formatValue(top.value)} (${top.count})`);
  }
  return lines.join('\n');
}

