function getUniqueChars(str) {
  if (typeof str !== 'string') {
    throw new TypeError('getUniqueChars expects a string');
  }
  const seen = new Set();
  let result = '';
  for (const ch of str) {
    if (!seen.has(ch)) {
      seen.add(ch);
      result += ch;
    }
  }
  return result;
}

function countCharacters(str) {
  const counts = new Map();
  for (const ch of str) {
    const previous = counts.get(ch);
    counts.set(ch, previous === undefined ? 1 : previous + 1);
  }
  return counts;
}

function countDuplicates(str) {
  let duplicates = 0;
  for (const total of countCharacters(str).values()) {
    if (total !== 1) {
      duplicates += total - 1;
    }
  }
  return duplicates;
}

function isAlreadyUnique(str) {
  return getUniqueChars(str).length === str.length;
}

function firstRepeatedChar(str) {
  const seen = new Set();
  for (const ch of str) {
    if (seen.has(ch)) {
      return ch;
    }
    seen.add(ch);
  }
  return null;
}

function describe(str) {
  const unique = getUniqueChars(str);
  const removed = countDuplicates(str);
  const shown = str.length === 0 ? '(empty string)' : `'${str}'`;
  const verdict = removed === 0 ? 'no repeats' : `${removed} character(s) dropped`;
  return `${shown} -> '${unique}' (${verdict})`;
}

function main() {
  const samples = ['hello world', 'aabbcc', 'abc', ''];
  for (const sample of samples) {
    console.log(describe(sample));
    const repeat = firstRepeatedChar(sample);
    if (repeat === null) {
      console.log('  first repeat: none');
    } else {
      console.log(`  first repeat: '${repeat}'`);
    }
    if (isAlreadyUnique(sample)) {
      console.log('  input was already unique');
    }
  }
}

main();

module.exports = {
  getUniqueChars,
  countCharacters,
  countDuplicates,
  isAlreadyUnique,
  firstRepeatedChar,
  describe,
};

