const VOWELS = 'aeiou';

function classifyChar(ch) {
  const lower = ch.toLowerCase();
  if (lower < 'a' || lower > 'z') {
    return 'other';
  }
  return VOWELS.indexOf(lower) === -1 ? 'consonant' : 'vowel';
}

function countVowelsAndConsonants(str) {
  if (typeof str !== 'string') {
    throw new TypeError('countVowelsAndConsonants expects a string');
  }
  const result = { vowels: 0, consonants: 0 };
  for (const ch of str) {
    const kind = classifyChar(ch);
    if (kind === 'vowel') {
      result.vowels += 1;
    } else if (kind === 'consonant') {
      result.consonants += 1;
    }
  }
  return result;
}

function dominantKind(counts) {
  if (counts.vowels === counts.consonants) {
    return 'balanced';
  }
  return counts.vowels > counts.consonants ? 'vowels' : 'consonants';
}

function letterRatio(counts) {
  const letters = counts.vowels + counts.consonants;
  if (letters === 0) {
    return null;
  }
  return counts.vowels / letters;
