function validateRowIndex(rowIndex) {
  if (typeof rowIndex !== 'number') {
    throw new TypeError('rowIndex must be a number');
  }
  if (!Number.isFinite(rowIndex)) {
    throw new RangeError('rowIndex must be finite');
  }
  if (Math.trunc(rowIndex) !== rowIndex) {
    throw new RangeError('rowIndex must be an integer');
  }
  if (rowIndex < 0) {
    throw new RangeError('rowIndex must be non-negative');
  }
  return rowIndex;
}

function parseRowIndices(args) {
  if (args.length === 0) {
    return [0, 3, 7];
  }
  return args.map((arg) => validateRowIndex(Number(arg)));
}

function generatePascalsRow(rowIndex) {
  validateRowIndex(rowIndex);
  const row = [1];
  for (let n = 1; n <= rowIndex; n += 1) {
    for (let k = row.length - 1; k >= 1; k -= 1) {
      row[k] = row[k] + row[k - 1];
    }
    row.push(1);
  }
  return row;
}

function isPalindromic(row) {
  for (let i = 0, j = row.length - 1; i < j; i += 1, j -= 1) {
    if (row[i] !== row[j]) {
      return false;
    }
  }
  return true;
}

function centralValues(row) {
  const mid = Math.floor(row.length / 2);
  if (row.length % 2 === 1) {
    return [row[mid]];
  }
  return [row[mid - 1], row[mid]];
}

function rowSum(row) {
  return row.reduce((total, value) => total + value, 0);
}

function formatRow(row, width) {
  return row.map((value) => String(value).padStart(width, ' ')).join(' ');
}

function buildTriangle(height) {
  validateRowIndex(height);
  const rows = [];
  for (let n = 0; n <= height; n += 1) {
    rows.push(generatePascalsRow(n));
  }
  return rows;
}

function renderTriangle(height) {
  const rows = buildTriangle(height);
  const last = rows[rows.length - 1];
  const width = String(Math.max(...last)).length;
  const fullWidth = formatRow(last, width).length;
  return rows
    .map((row) => {
      const text = formatRow(row, width);
      return ' '.repeat(Math.floor((fullWidth - text.length) / 2)) + text;
    })
    .join('\n');
}

function describeRow(rowIndex) {
  const row = generatePascalsRow(rowIndex);
  const symmetric = isPalindromic(row) ? 'symmetric' : 'asymmetric';
  const peak = centralValues(row).join('/');
  return `row ${rowIndex}: [${row.join(', ')}] (${symmetric}, sum=${rowSum(row)}, peak=${peak})`;
}

function main(argv) {
  const indices = parseRowIndices(argv.slice(2));
  indices.forEach((index) => console.log(describeRow(index)));
  console.log(renderTriangle(Math.max(...indices)));
}

main(process.argv);

module.exports = { generatePascalsRow, buildTriangle, renderTriangle, describeRow };

