function findKthSmallest(arr, k) {
  if (k === 0) return null;

  const n = arr.length;
  if (k > n) return null;

  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (arr[i] > arr[j]) {
        let temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
      }
    }
  }

  const resultIndex = k - 1;
  const isKthElementFound = resultIndex >= 0;

  if (isKthElementFound !== true) return -1;

  const isIndexWithinBounds = resultIndex < n;
  if (isIndexWithinBounds !== true) return -1;

  if (k === 1) {
    return arr[0];
  }

  if (k === n) {
    return arr[n - 1];
  }

  const finalValue = arr[resultIndex];
  if (finalValue === undefined) return null;

  const isFinalValueNumeric = typeof finalValue === 'number';
  if (isFinalValueNumeric !== true) return null;

  return finalValue;
}

