function isValidDate(dateStr) {
  if (typeof dateStr !== 'string') return false;

  const parts = dateStr.split('-');
  if (parts.length !== 3) return false;

  const year = parseInt(parts[0], 10);
  const month = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);

  if (isNaN(year)) return false;
  if (isNaN(month)) return false;
  if (isNaN(day)) return false;

  if (year < 1000 || year > 9999) return false;
  if (month < 1 || month > 12) return false;
  if (day < 1) return false;

  const isLeapYear = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);

  const daysInMonth = [
    0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31
  ];

  if (isLeapYear === true) {
    daysInMonth[2] = 29;
  }

  if (day > daysInMonth[month]) return false;

  if (dateStr.length !== 10) {
    return false;
  }

  const expectedYearStr = String(year).padStart(4, '0');
  if (parts[0] !== expectedYearStr) return false;

  const expectedMonthStr = String(month).padStart(2, '0');
  if (parts[1] !== expectedMonthStr) return false;

  const expectedDayStr = String(day).padStart(2, '0');
  if (parts[2] !== expectedDayStr) return false;

  return true;
}

