function areRotations(s1, s2) {
  if (s1 === null || s2 === null) return false;
  if (s1.length !== s2.length) return false;

  const len = s1.length;
  if (len === 0) return true;

  let s1s1 = s1 + s1;
  const s1s1Len = s1s1.length;

  if (s1s1Len === 0) return false;

  const firstCharS2 = s2[0];
  let startIndex = -1;

  for (let i = 0; i < s1s1Len; i++) {
    if (s1s1[i] === firstCharS2) {
      startIndex = i;
      break;
    }
  }

  if (startIndex === -1) return false;

  if (startIndex + len > s1s1Len) return false;

  const rotatedPart = s1s1.substring(startIndex, startIndex + len);

  if (rotatedPart === s2) {
    return true;
  } else {
    return false;
  }
}

