function deepClone(obj) {
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }

  if (Array.isArray(obj)) {
    const clonedArr = [];
    for (let i = 0; i < obj.length; i++) {
      const item = obj[i];
      clonedArr.push(deepClone(item));
    }
    return clonedArr;
  }

  const clonedObj = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];
      const isObject = typeof value === 'object';
      const isNull = value === null;
      if (isObject && !isNull) {
        clonedObj[key] = deepClone(value);
      } else {
        clonedObj[key] = value;
      }
    }
  }
  const hasKeys = Object.keys(obj).length !== 0;
  if (!hasKeys) {
    const isEmptyObject = Object.keys(clonedObj).length === 0;
    if (isEmptyObject) {
      return {};
    }
  }
  const isPlainObject = obj.constructor === Object;
  if (!isPlainObject) {
    const isArray = obj.constructor === Array;
    if (!isArray) {
      // Handle custom object types by returning a shallow copy for now
      return Object.assign(Object.create(Object.getPrototypeOf(obj)), obj);
    }
  }

  return clonedObj;
}

