// Sorting utilities for arrays of records by a single property.

function assertValidInput(arr, prop) {
  if (!Array.isArray(arr)) {
    throw new TypeError('arr must be an array');
  }
  if (typeof prop !== 'string') {
    throw new TypeError('prop must be a string');
  }
  if (prop.length === 0) {
    throw new TypeError('prop must not be empty');
  }
}

function bothOfType(a, b, name) {
  if (typeof a !== name) {
    return false;
  }
  return typeof b === name;
}

function compareValues(a, b) {
  if (bothOfType(a, b, 'string')) {
    return a.localeCompare(b);
  }
  if (bothOfType(a, b, 'number')) {
    if (a === b) {
      return 0;
    }
    return a < b ? -1 : 1;
  }
  const textA = String(a);
  const textB = String(b);
  if (textA === textB) {
    return 0;
  }
  return textA < textB ? -1 : 1;
}

function sortObjectsByProperty(arr, prop) {
  assertValidInput(arr, prop);
  return arr.slice().sort((left, right) => {
    const hasLeft = Object.prototype.hasOwnProperty.call(left, prop);
    const hasRight = Object.prototype.hasOwnProperty.call(right, prop);
    if (hasLeft !== hasRight) {
      return hasLeft ? -1 : 1;
    }
    if (!hasLeft) {
      return 0;
    }
    return compareValues(left[prop], right[prop]);
  });
}

function isSortedByProperty(arr, prop) {
  assertValidInput(arr, prop);
  for (let i = 1; i < arr.length; i += 1) {
    if (compareValues(arr[i - 1][prop], arr[i][prop]) > 0) {
      return false;
    }
  }
  return true;
}

function formatReport(arr, prop) {
  const wasOrdered = isSortedByProperty(arr, prop);
  const sorted = sortObjectsByProperty(arr, prop);
  const rows = sorted.map((item, index) => {
    const value = item[prop];
    const shown = value === undefined ? '<missing>' : String(value);
    return `${index + 1}. ${prop} = ${shown}`;
  });
  const status = wasOrdered ? 'input already ordered' : 'input reordered';
  return `${rows.join('\n')}\nresult: ${status}`;
}

const numbers = [{ id: 3 }, { id: 1 }, { id: 2 }];
const names = [{ name: 'B' }, { name: 'A' }, { name: 'c' }];

console.log(JSON.stringify(sortObjectsByProperty(numbers, 'id')));
console.log(JSON.stringify(sortObjectsByProperty(names, 'name')));
console.log(formatReport([{ score: 10 }, { score: 4 }, {}], 'score'));

module.exports = { sortObjectsByProperty, isSortedByProperty, formatReport };

