// JSON validation utilities

function isValidJSON(jsonStr) {
  if (typeof jsonStr !== 'string') {
    return false;
  }
  if (jsonStr.trim() === '') {
    return false;
  }
  try {
    JSON.parse(jsonStr);
    return true;
  } catch (err) {
    return false;
  }
}

function describeError(jsonStr) {
  try {
    JSON.parse(jsonStr);
    return null;
  } catch (err) {
    return err.message;
  }
}

function rootKind(jsonStr) {
  if (!isValidJSON(jsonStr)) {
    return 'invalid';
  }
  const value = JSON.parse(jsonStr);
  if (value === null) {
    return 'null';
  }
  if (Array.isArray(value)) {
    return 'array';
  }
  const kind = typeof value;
  if (kind === 'object') {
    return 'object';
  }
  return kind;
}

function formatReport(jsonStr) {
  const label = JSON.stringify(jsonStr);
  const kind = rootKind(jsonStr);
  if (kind === 'invalid') {
    const reason = describeError(jsonStr);
    if (reason === null) {
      return label + ' -> invalid (empty or non-string input)';
    }
    return label + ' -> invalid: ' + reason;
  }
  return label + ' -> valid (' + kind + ')';
}

function main() {
  const samples = [
    '{"name": "Alice"}',
    '{"name": "Alice",}',
    '[1, 2, 3]',
    '"just a string"',
    'null',
    '42',
    '',
    "{'name': 'Alice'}"
  ];
  let validCount = 0;
  for (const sample of samples) {
    if (isValidJSON(sample)) {
      validCount += 1;
    }
    console.log(formatReport(sample));
  }
  const plural = validCount === 1 ? 'sample' : 'samples';
  console.log(validCount + ' valid ' + plural + ' out of ' + samples.length);
}

main();

