function isDigitChar(ch) {
  return ch >= '0' && ch <= '9';
}

function extractDigits(str) {
  if (typeof str !== 'string') {
    throw new TypeError('extractDigits expects a string');
  }
  let digits = '';
  for (let i = 0; i < str.length; i += 1) {
    const ch = str.charAt(i);
    if (isDigitChar(ch)) {
      digits += ch;
    }
  }
  return digits;
}

function stripLeadingZeros(digits) {
  let start = 0;
  while (start < digits.length - 1 && digits.charAt(start) === '0') {
    start += 1;
  }
  return digits.slice(start);
}

function toNumber(str) {
  const digits = extractDigits(str);
  if (digits === '') {
    return null;
  }
  return Number(stripLeadingZeros(digits));
}

function describe(str) {
  const digits = extractDigits(str);
  const total = digits.length;
  if (total === 0) {
    return JSON.stringify(str) + ' -> "" (no digits)';
  }
  const trimmed = stripLeadingZeros(digits);
  let note;
  if (total === 1) {
    note = '1 digit';
  } else {
    note = total + ' digits';
  }
  if (trimmed !== digits) {
    note += ', leading zeros trimmed';
  }
  return JSON.stringify(str) + ' -> "' + digits + '" (' + note + ', value ' + Number(trimmed) + ')';
}

function main() {
  const samples = ['abc123def45', 'no numbers here', 'order #0042 shipped', 'pi is 3.14159', '7'];
  const report = samples.map(describe);
  report.forEach(function (line) {
    console.log(line);
  });
  const emptyCount = samples.filter(function (sample) {
    return extractDigits(sample) === '';
  }).length;
  console.log('samples without digits: ' + emptyCount);
  const values = samples.map(toNumber).filter(function (value) {
    return value !== null;
  });
  console.log('largest value: ' + Math.max.apply(null, values));
}

main();

