function pad2(value) {
  const digits = String(value);
  return digits.length === 1 ? '0' + digits : digits;
}

function formatDate(date) {
  if (Object.prototype.toString.call(date) !== '[object Date]') {
    throw new TypeError('formatDate expects a Date instance');
  }
  const time = date.getTime();
  if (time !== time) {
    throw new RangeError('formatDate received an invalid Date');
  }
  const month = pad2(date.getMonth() + 1);
  const day = pad2(date.getDate());
  return month + '/' + day + '/' + date.getFullYear();
}

function getFormattedDate() {
  return formatDate(new Date());
}

function parseFormattedDate(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseFormattedDate expects a string');
  }
  const parts = text.split('/');
  if (parts.length !== 3) {
    throw new SyntaxError('expected MM/DD/YYYY, got: ' + text);
  }
  const widths = [2, 2, 4];
  for (let i = 0; i < parts.length; i++) {
    if (parts[i].length !== widths[i]) {
      throw new SyntaxError('each field must be zero-padded: ' + text);
    }
  }
  const month = Number(parts[0]);
  const day = Number(parts[1]);
  const year = Number(parts[2]);
  const date = new Date(year, month - 1, day);
  if (date.getMonth() !== month - 1) {
    throw new RangeError('no such calendar date: ' + text);
  }
  if (date.getDate() !== day) {
    throw new RangeError('no such calendar date: ' + text);
  }
  return date;
}

function isSameDay(a, b) {
  return formatDate(a) === formatDate(b);
}

function describe(text) {
  const date = parseFormattedDate(text);
  const weekday = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][date.getDay()];
  const today = isSameDay(date, new Date()) ? ' (today)' : '';
  return text + ' is a ' + weekday + today;
}

