function charCase(ch) {
  if (ch >= 'a' && ch <= 'z') return 'lower';
  if (ch >= 'A' && ch <= 'Z') return 'upper';
  return 'other';
}

function generateCharRange(startChar, endChar) {
  const startCase = charCase(startChar);
  if (startCase === 'other') {
    throw new RangeError(`start character ${startChar} is not a letter`);
  }
  const endCase = charCase(endChar);
  if (endCase === 'other') {
    throw new RangeError(`end character ${endChar} is not a letter`);
  }
  if (startCase !== endCase) {
    throw new RangeError('start and end must share the same case');
  }

  const from = startChar.charCodeAt(0);
  const to = endChar.charCodeAt(0);
  const step = from <= to ? 1 : -1;
  const range = [];

  for (let code = from; ; code += step) {
    range.push(String.fromCharCode(code));
    if (code === to) break;
  }
  return range;
}

function isVowel(ch) {
  return 'aeiou'.includes(ch.toLowerCase());
}

function describeRange(startChar, endChar) {
  const chars = generateCharRange(startChar, endChar);
  let vowels = 0;
  for (const ch of chars) {
    if (isVowel(ch)) vowels += 1;
  }
  let direction = 'ascending';
  if (chars.length === 1) {
    direction = 'single';
  } else if (startChar > endChar) {
    direction = 'descending';
  }
  return {
    chars,
    length: chars.length,
    vowels,
    consonants: chars.length - vowels,
    letterCase: charCase(startChar),
    direction
  };
}

function formatReport(startChar, endChar) {
  let info;
  try {
    info = describeRange(startChar, endChar);
  } catch (err) {
    return `${startChar}..${endChar}: error - ${err.message}`;
  }
  const plural = info.length === 1 ? 'char' : 'chars';
  const parts = [
    `${startChar}..${endChar} (${info.letterCase}, ${info.direction})`,
    `${info.length} ${plural}`,
    `${info.vowels} vowel(s)`,
    `${info.consonants} consonant(s)`,
    info.chars.join('')
  ];
  return parts.join(' | ');
}

function main() {
  const pairs = [['a', 'd'], ['X', 'Z'], ['q', 'q'], ['h', 'b'], ['a', 'Z'], ['1', '5']];
  for (const [start, end] of pairs) {
    console.log(formatReport(start, end));
  }
}

main();

