    return false;
  }
  if (trimmed.lastIndexOf('@') != at) {
    return false;
  }
  const dot = trimmed.indexOf('.', at);
  if (dot == -1) {
    return false;
  }
  return at > 0 && dot > at + 1 && dot < trimmed.length - 1;
}

function splitEmail(email) {
  if (!isValidEmail(email)) {
    return null;
  }
  const trimmed = email.trim();
  const at = trimmed.indexOf('@');
  return { local: trimmed.slice(0, at), domain: trimmed.slice(at + 1) };
}

function explain(email) {
  if (typeof email != 'string') {
    return 'not a string';
  }
  const trimmed = email.trim();
  if (trimmed == '') {
    return 'empty string';
  }
  const at = trimmed.indexOf('@');
  if (at == -1) {
    return "missing '@'";
  }
  if (trimmed.lastIndexOf('@') != at) {
    return "more than one '@'";
  }
  if (at == 0) {
    return 'missing local part';
  }
  if (trimmed.indexOf('.', at) == -1) {
    return "missing '.' after '@'";
  }
  if (isValidEmail(trimmed)) {
    return 'valid';
  }
  return 'malformed domain';
}

function report(candidates) {
  const lines = [];
  for (const candidate of candidates) {
    const label = typeof candidate == 'string' ? JSON.stringify(candidate) : String(candidate);
    const verdict = isValidEmail(candidate);
    const parts = splitEmail(candidate);
    const detail = parts == null ? explain(candidate) : parts.local + ' at ' + parts.domain;
    lines.push(label + ' -> ' + verdict + ' (' + detail + ')');
  }
  return lines.join('\n');
}

const samples = ['test@example.com', 'invalid-email', 'a@b.c', '@nolocal.org', 'two@@dots.net', '  spaced@mail.io  ', 42];
console.log(report(samples));

const validCount = samples.filter(isValidEmail).length;
console.log('valid: ' + validCount + ' of ' + samples.length);
console.log(validCount == samples.length ? 'all addresses passed' : 'some addresses failed');

