function updateStock(inventory, item, quantityChange) {
  if (typeof item !== 'string') {
    throw new TypeError('item must be a string');
  }
  const key = item.trim();
  if (key === '') {
    throw new TypeError('item must not be blank');
  }
  if (typeof quantityChange !== 'number' || !Number.isInteger(quantityChange)) {
    throw new TypeError('quantityChange must be an integer');
  }

  const current = Object.prototype.hasOwnProperty.call(inventory, key) ? inventory[key] : 0;
  const next = current + quantityChange;
  inventory[key] = next < 0 ? 0 : next;
  return inventory;
}

function applyDeliveries(inventory, deliveries) {
  for (const entry of deliveries) {
    updateStock(inventory, entry.item, entry.change);
  }
  return inventory;
}

function stockStatus(inventory, item) {
  if (!Object.prototype.hasOwnProperty.call(inventory, item)) {
    return 'unknown';
  }
  const level = inventory[item];
  if (level === 0) {
    return 'out of stock';
  }
  return level < 5 ? 'low' : 'ok';
}

function formatReport(inventory) {
  const names = Object.keys(inventory).sort();
  if (names.length === 0) {
    return '(empty inventory)';
  }
  let width = 0;
  for (const name of names) {
    if (name.length > width) {
      width = name.length;
    }
  }
  const lines = [];
  for (const name of names) {
    const status = stockStatus(inventory, name);
    const suffix = status === 'ok' ? '' : '  <- ' + status;
    lines.push(name.padEnd(width, ' ') + '  ' + String(inventory[name]).padStart(3, ' ') + suffix);
  }
  return lines.join('\n');
}

function main() {
  const inventory = { apple: 10, banana: 5 };

  updateStock(inventory, 'apple', -3);
  updateStock(inventory, 'orange', 2);
  updateStock(inventory, 'banana', -12);

  applyDeliveries(inventory, [
    { item: 'pear', change: 8 },
    { item: 'orange', change: 3 },
    { item: 'apple', change: -7 }
  ]);

  if (stockStatus(inventory, 'kiwi') === 'unknown') {
    console.log('kiwi is not tracked yet; adding a starter batch');
    updateStock(inventory, 'kiwi', 4);
  }

  const empties = Object.keys(inventory).filter(function (name) {
    return inventory[name] === 0;
  });
  console.log('items at zero: ' + (empties.length === 0 ? 'none' : empties.join(', ')));
  console.log(formatReport(inventory));
}

main();

module.exports = { updateStock, applyDeliveries, stockStatus, formatReport };

