const VALID_CHOICES = ['rock', 'paper', 'scissors'];

const BEATS = {
  rock: 'scissors',
  paper: 'rock',
  scissors: 'paper'
};

function normalizeChoice(choice) {
  if (typeof choice !== 'string') {
    throw new TypeError('A choice must be given as a string');
  }
  const cleaned = choice.trim().toLowerCase();
  if (VALID_CHOICES.indexOf(cleaned) === -1) {
    throw new RangeError('Unknown choice: ' + choice);
  }
  return cleaned;
}

function playRPS(player1Choice, player2Choice) {
  const first = normalizeChoice(player1Choice);
  const second = normalizeChoice(player2Choice);
  if (first === second) {
    return 'Tie';
  }
  if (BEATS[first] === second) {
    return 'Player 1';
  }
  return 'Player 2';
}

function playMatch(rounds) {
  const tally = { 'Player 1': 0, 'Player 2': 0, Tie: 0 };
  const results = rounds.map(function (round, index) {
    const winner = playRPS(round[0], round[1]);
    tally[winner] += 1;
    return { number: index + 1, p1: round[0], p2: round[1], winner: winner };
  });
  return { results: results, tally: tally };
}

function describeRound(round) {
  const header = 'Round ' + round.number + ': ' + round.p1 + ' vs ' + round.p2 + ' -> ';
  if (round.winner === 'Tie') {
    return header + 'nobody scores';
  }
  return header + round.winner + ' wins';
}

function matchVerdict(tally) {
  if (tally['Player 1'] === tally['Player 2']) {
    return 'The match is drawn ' + tally['Player 1'] + '-' + tally['Player 2'];
  }
  const leader = tally['Player 1'] > tally['Player 2'] ? 'Player 1' : 'Player 2';
  const high = Math.max(tally['Player 1'], tally['Player 2']);
  const low = Math.min(tally['Player 1'], tally['Player 2']);
  return leader + ' takes the match ' + high + '-' + low;
}

function main() {
  const rounds = [
    ['rock', 'scissors'],
    ['paper', 'paper'],
    ['Scissors', 'rock'],
    ['paper', 'rock'],
    ['rock', ' ROCK ']
  ];
  const match = playMatch(rounds);
  match.results.forEach(function (round) {
    console.log(describeRound(round));
  });
  if (match.tally.Tie !== 0) {
    console.log('Tied rounds: ' + match.tally.Tie);
  }
  console.log(matchVerdict(match.tally));

  try {
    playRPS('rock', 'lizard');
  } catch (err) {
    console.log('Rejected input: ' + err.message);
  }
}

main();

