function validateInputs(principal, rate, n, years) {
  const labels = ['principal', 'rate', 'n', 'years'];
  const values = [principal, rate, n, years];
  for (let i = 0; i < values.length; i++) {
    if (typeof values[i] !== 'number' || !Number.isFinite(values[i])) {
      throw new TypeError(labels[i] + ' must be a finite number');
    }
    if (values[i] < 0) {
      throw new RangeError(labels[i] + ' must not be negative');
    }
  }
  if (Math.floor(n) !== n) {
    throw new RangeError('n must be a whole number of periods per year');
  }
  if (n === 0) {
    throw new RangeError('n must be at least 1 compounding period per year');
  }
}

function calculateCompoundInterest(principal, rate, n, years) {
  validateInputs(principal, rate, n, years);
  return principal * Math.pow(1 + rate / n, n * years);
}

function interestEarned(principal, rate, n, years) {
  return calculateCompoundInterest(principal, rate, n, years) - principal;
}

function periodName(n) {
  if (n === 1) {
    return 'annually';
  }
  if (n === 2) {
    return 'semi-annually';
  }
  if (n === 4) {
    return 'quarterly';
  }
  if (n === 12) {
    return 'monthly';
  }
  if (n === 365) {
    return 'daily';
  }
  return n + ' times per year';
}

function formatMoney(amount) {
  const rounded = Math.round(amount * 100) / 100;
  const sign = rounded < 0 ? '-' : '';
  return sign + '$' + Math.abs(rounded).toFixed(2);
}

function describeGrowth(principal, rate, n, years) {
  const final = calculateCompoundInterest(principal, rate, n, years);
  const gain = interestEarned(principal, rate, n, years);
  const span = years === 1 ? '1 year' : years + ' years';
  const growth = gain === 0 ? 'no growth' : 'earning ' + formatMoney(gain);
  return formatMoney(principal) + ' compounded ' + periodName(n) +
    ' for ' + span + ' becomes ' + formatMoney(final) + ' (' + growth + ')';
}

function main() {
  const scenarios = [
    [1000, 0.05, 4, 1],
    [5000, 0.03, 12, 5],
    [2500, 0.0, 1, 10],
    [10000, 0.07, 365, 3]
  ];
  let totalGain = 0;
  for (const [principal, rate, n, years] of scenarios) {
    console.log(describeGrowth(principal, rate, n, years));
    totalGain += interestEarned(principal, rate, n, years);
  }
  console.log('Total interest across all scenarios: ' + formatMoney(totalGain));
}

main();

